#!/usr/bin/env python3
"""Simple test to verify the code changes are syntactically correct."""

import ast
import sys

def check_file_syntax(filepath):
    """Check if a Python file has valid syntax."""
    try:
        with open(filepath, 'r') as f:
            code = f.read()
        ast.parse(code)
        print(f"✓ {filepath} - syntax is valid")
        return True
    except SyntaxError as e:
        print(f"✗ {filepath} - syntax error: {e}")
        return False

def main():
    files_to_check = [
        "vllm/model_executor/layers/mamba/ops/ssd_chunk_scan.py",
        "vllm/model_executor/layers/mamba/ops/ssd_combined.py",
        "vllm/model_executor/layers/mamba/mamba_mixer.py",
        "vllm/model_executor/layers/mamba/mamba_mixer2.py",
        "vllm/model_executor/models/phi4flash.py",
        "vllm/model_executor/models/plamo2.py",
    ]

    all_valid = True
    for filepath in files_to_check:
        if not check_file_syntax(filepath):
            all_valid = False

    if all_valid:
        print("\n✓ All files have valid syntax!")
        return 0
    else:
        print("\n✗ Some files have syntax errors!")
        return 1

if __name__ == "__main__":
    sys.exit(main())

